+<?php
+error_reporting(E_ALL);
+ini_set('display_errors', 1);
+
+echo "<h1>SMTP Standalone Test</h1>";
+
+// Function to send test email
+function sendTestEmail() {
+    $to = 'veripoolresort@gmail.com';
+    $subject = 'Test Email from IMS - ' . date('Y-m-d H:i:s');
+    $message = '<h2>Test Email</h2><p>If you receive this, your SMTP is working!</p>';
+    
+    // Headers
+    $headers = "MIME-Version: 1.0\r\n";
+    $headers .= "Content-Type: text/html; charset=UTF-8\r\n";
+    $headers .= "From: veripoolresort@gmail.com\r\n";
+    
+    // Try PHP mail() first
+    if (mail($to, $subject, $message, $headers)) {
+        echo "<p style='color:green'>✓ PHP mail() succeeded</p>";
+        return true;
+    } else {
+        echo "<p style='color:red'>✗ PHP mail() failed</p>";
+        return false;
+    }
+}
+
+// Test PHP mail
+sendTestEmail();
+
+// Check if PHPMailer exists
+echo "<h2>Checking PHPMailer</h2>";
+if (file_exists(__DIR__ . '/vendor/autoload.php')) {
+    echo "<p style='color:green'>✓ Composer autoload found</p>";
+    require_once __DIR__ . '/vendor/autoload.php';
+    
+    use PHPMailer\PHPMailer\PHPMailer;
+    use PHPMailer\PHPMailer\Exception;
+    
+    // Test PHPMailer
+    $mail = new PHPMailer(true);
+    
+    try {
+        $mail->SMTPDebug = 2; // Detailed debug output
+        $mail->isSMTP();
+        $mail->Host = 'smtp.gmail.com';
+        $mail->SMTPAuth = true;
+        $mail->Username = 'veripoolresort@gmail.com';
+        $mail->Password = str_replace(' ', '', 'vxox gejv drub hwpz');
+        $mail->SMTPSecure = 'tls';
+        $mail->Port = 587;
+        $mail->setFrom('veripoolresort@gmail.com', 'IMS System');
+        $mail->addAddress('veripoolresort@gmail.com');
+        $mail->isHTML(true);
+        $mail->Subject = 'PHPMailer Test - ' . date('Y-m-d H:i:s');
+        $mail->Body = '<h2>PHPMailer Test</h2><p>This email was sent using PHPMailer!</p>';
+        
+        if ($mail->send()) {
+            echo "<p style='color:green; font-size:16px; font-weight:bold;'>✓ PHPMailer test email sent successfully!</p>";
+        } else {
+            echo "<p style='color:red'>✗ PHPMailer error: " . $mail->ErrorInfo . "</p>";
+        }
+    } catch (Exception $e) {
+        echo "<p style='color:red'>✗ Exception: " . $e->getMessage() . "</p>";
+        echo "<p>Mailer Error: " . $mail->ErrorInfo . "</p>";
+    }
+} else {
+    echo "<p style='color:red'>✗ Composer autoload not found. Installing PHPMailer...</p>";
+    
+    // Check if PHPMailer exists in alternative location
+    if (file_exists(__DIR__ . '/PHPMailer/src/PHPMailer.php')) {
+        echo "<p style='color:orange'>PHPMailer found in manual installation</p>";
+        require_once __DIR__ . '/PHPMailer/src/Exception.php';
+        require_once __DIR__ . '/PHPMailer/src/PHPMailer.php';
+        require_once __DIR__ . '/PHPMailer/src/SMTP.php';
+        
+        use PHPMailer\PHPMailer\PHPMailer;
+        use PHPMailer\PHPMailer\Exception;
+        
+        $mail = new PHPMailer(true);
+        
+        try {
+            $mail->SMTPDebug = 2;
+            $mail->isSMTP();
+            $mail->Host = 'smtp.gmail.com';
+            $mail->SMTPAuth = true;
+            $mail->Username = 'veripoolresort@gmail.com';
+            $mail->Password = str_replace(' ', '', 'vxox gejv drub hwpz');
+            $mail->SMTPSecure = 'tls';
+            $mail->Port = 587;
+            $mail->setFrom('veripoolresort@gmail.com', 'IMS System');
+            $mail->addAddress('veripoolresort@gmail.com');
+            $mail->isHTML(true);
+            $mail->Subject = 'Manual PHPMailer Test - ' . date('Y-m-d H:i:s');
+            $mail->Body = '<h2>Manual PHPMailer Test</h2><p>This email was sent using manually installed PHPMailer!</p>';
+            
+            if ($mail->send()) {
+                echo "<p style='color:green'>✓ Manual PHPMailer test successful!</p>";
+            } else {
+                echo "<p style='color:red'>✗ Manual PHPMailer error: " . $mail->ErrorInfo . "</p>";
+            }
+        } catch (Exception $e) {
+            echo "<p style='color:red'>✗ Exception: " . $e->getMessage() . "</p>";
+        }
+    } else {
+        echo "<p style='color:red'>✗ PHPMailer not found. Please run: composer require phpmailer/phpmailer</p>";
+        echo "<p>Or download PHPMailer manually from https://github.com/PHPMailer/PHPMailer</p>";
+    }
+}
+
+// Display PHP configuration
+echo "<h2>PHP Configuration</h2>";
+echo "<ul>";
+echo "<li>PHP Version: " . phpversion() . "</li>";
+echo "<li>OpenSSL loaded: " . (extension_loaded('openssl') ? 'Yes' : 'No') . "</li>";
+echo "<li>cURL loaded: " . (extension_loaded('curl') ? 'Yes' : 'No') . "</li>";
+echo "<li>allow_url_fopen: " . (ini_get('allow_url_fopen') ? 'On' : 'Off') . "</li>";
+echo "</ul>";
+?>
